/**
 * Os 278 campos do Anexo B (`docs/produto/2026-11-24-ia-anexo-b-mapa-campos-consulta.md`), um por
 * linha, na ordem do documento: seção e grupo da página, rótulo de tela, como aparece, formato e as
 * classificações em que o campo vem preenchido na base (colunas A, H, R, D, L e P diferentes de "—").
 *
 * O rótulo é o do Anexo B sem as anotações entre parênteses e sem o que vem depois de ";"; "(%)" e
 * "(sigla)" ficam, porque separam pares de campos. O que cada molde mostra está em `moldes.ts`.
 */

import type { Classificacao } from "@/lib/consulta/consulta";

export type Aparece = "visivel" | "recolhido" | "moeda" | "quando-houver";

export type Formato =
  | "texto"
  | "dinheiro"
  | "data"
  | "dataHora"
  | "hora"
  | "inteiro"
  | "percentual"
  | "cambio"
  | "booleano"
  | "lista";

export interface CampoAnexo {
  caminho: string;
  secao: 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9;
  grupo: string;
  rotulo: string;
  /** A regra geral da coluna "Aparece". */
  aparece: Aparece;
  /** As exceções por classificação ("recolhido; no rodoviário, visível"). */
  apareceNa?: { classificacao: Classificacao; aparece: Aparece }[];
  formato: Formato;
  classes: Classificacao[];
  /** A lista que só contém os itens: nunca aparece como valor; aparecem os campos dos itens. */
  conteiner: boolean;
}

